//! Expectations generated by the PHP package, not by the Rust implementation.

use serde_json::{Value, json};
use spatie_robots_txt::{RobotsHeaders, RobotsMeta, RobotsTxt};

#[test]
fn matches_php_rules_delays_and_diagnostic_reasons() {
    let fixtures: Value = serde_json::from_str(include_str!("fixtures/php.json")).unwrap();
    for case in fixtures["txt"].as_array().unwrap() {
        for mode in case["modes"].as_array().unwrap() {
            let mut robots = RobotsTxt::create(case["content"].as_str().unwrap());
            if mode["partial"] == true {
                robots = robots.with_partial_matches();
            }
            if mode["ignoreGlobal"] == true {
                robots = robots.ignore_global_group();
            }
            for check in mode["checks"].as_array().unwrap() {
                let path = check["path"].as_str().unwrap();
                let agent = check["agent"].as_str().unwrap();
                assert_eq!(
                    json!(robots.allows_for(path, agent)),
                    check["allows"],
                    "{} partial={} ignoreGlobal={} {agent:?} {path:?}",
                    case["name"],
                    mode["partial"],
                    mode["ignoreGlobal"]
                );
                let reasons = robots.why_disallows(path, agent).map(|reasons| reasons.into_iter().map(|reason| json!({"userAgent": reason.user_agent, "basePath": reason.base_path})).collect::<Vec<_>>());
                assert_eq!(
                    json!(reasons),
                    check["reasons"],
                    "{} {agent:?} {path:?}",
                    case["name"]
                );
            }
            for (agent, delay) in mode["delays"].as_object().unwrap() {
                assert_eq!(
                    json!(robots.crawl_delay_for(agent)),
                    *delay,
                    "{} {agent:?}",
                    case["name"]
                );
            }
        }
    }
}

#[test]
fn matches_php_meta_tag_syntax_and_directives() {
    let fixtures: Value = serde_json::from_str(include_str!("fixtures/php.json")).unwrap();
    for case in fixtures["meta"].as_array().unwrap() {
        let robots = RobotsMeta::create(case["html"].as_str().unwrap());
        assert_eq!(
            json!([
                robots.may_index(),
                robots.may_follow(),
                robots.noindex(),
                robots.nofollow()
            ]),
            case["result"],
            "{}",
            case["html"]
        );
    }
}

#[test]
fn matches_php_global_scoped_and_repeated_headers() {
    let fixtures: Value = serde_json::from_str(include_str!("fixtures/php.json")).unwrap();
    for case in fixtures["headers"].as_array().unwrap() {
        let robots = RobotsHeaders::create(
            case["lines"]
                .as_array()
                .unwrap()
                .iter()
                .map(|line| line.as_str().unwrap()),
        );
        let agent = case["agent"].as_str().unwrap();
        assert_eq!(
            json!([
                robots.may_index_for(agent),
                robots.may_follow_for(agent),
                robots.noindex_for(agent),
                robots.nofollow_for(agent),
                robots.none_for(agent)
            ]),
            case["result"],
            "{case}"
        );
    }
}
